import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import sortTags from 'ext:flarum/tags/common/utils/sortTags';
/**
 * The "tags as a field" option: a single tag (plus its parent) picked from a dropdown.
 */
export default class FieldEditTags extends Component {
  view() {
    const {
      selected,
      onchange,
      inputId
    } = this.attrs;
    const tags = this.selectableTags();
    if (this.maxPrimary() > 1 || this.maxSecondary() > 1) {
      return m("div", {
        className: "Alert"
      }, app.translator.trans('fof-mason.forum.tags.inadequate-settings'));
    }

    // A child tag implies its parent, so the child identifies the selection.
    const current = selected.find(tag => tag.parent()) || selected[0];
    return m("span", {
      className: "Select"
    }, m("select", {
      id: inputId,
      className: "Select-input FormControl",
      onchange: event => {
        const tag = tags.find(candidate => candidate.id() === event.target.value);
        const parent = tag?.parent();
        onchange(tag ? [tag, ...(parent ? [parent] : [])] : []);
      }
    }, m("option", {
      value: "",
      selected: !current,
      disabled: this.required(),
      hidden: this.required()
    }, app.translator.trans(this.required() ? 'fof-mason.forum.answers.choose-option' : 'fof-mason.forum.answers.no-option-selected')), tags.map(tag => {
      const parent = tag.parent();
      return m("option", {
        value: tag.id(),
        selected: tag === current
      }, (parent ? parent.name() + ' | ' : '') + tag.name());
    })), m(Icon, {
      name: "fas fa-caret-down",
      className: "Select-caret"
    }));
  }
  static label() {
    return app.forum.attribute('fof-mason.tags-field-name') || app.translator.trans('fof-mason.forum.tags.tags-label', {}, true);
  }
  required() {
    return app.forum.attribute('minPrimaryTags') > 0 || app.forum.attribute('minSecondaryTags') > 0;
  }
  maxPrimary() {
    return app.forum.attribute('maxPrimaryTags');
  }
  maxSecondary() {
    return app.forum.attribute('maxSecondaryTags');
  }
  selectableTags() {
    const {
      discussion
    } = this.attrs;
    const current = discussion ? discussion.tags() || [] : [];
    let tags = app.store.all('tags').filter(tag => discussion ? tag.canAddToDiscussion() || current.includes(tag) : tag.canStartDiscussion());
    if (this.maxPrimary() <= 0) tags = tags.filter(tag => !tag.isPrimary());
    if (this.maxSecondary() <= 0) tags = tags.filter(tag => tag.isPrimary());
    return sortTags(tags);
  }
}
flarum.reg.add('fof-mason', 'forum/components/FieldEditTags', FieldEditTags);