import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
export default class FieldEditText extends Component {
  view() {
    const {
      field,
      answers,
      onchange,
      inputId
    } = this.attrs;
    return m("input", {
      id: inputId,
      className: "FormControl",
      value: answers[0]?.content() ?? '',
      placeholder: app.forum.attribute('fof-mason.labels-as-placeholders') ? `${field.name()}${field.required() ? ' *' : ''}` : '',
      oninput: event => {
        const content = event.target.value;

        // An unsaved answer: patchModelIdentifier sends it inline so the server creates it with the discussion.
        onchange(content === '' ? [] : [app.store.createRecord('mason-answers', {
          attributes: {
            content
          },
          relationships: {
            field: {
              data: {
                type: 'mason-fields',
                id: field.id()
              }
            }
          }
        })]);
      }
    });
  }
}
flarum.reg.add('fof-mason', 'forum/components/FieldEditText', FieldEditText);