import app from 'flarum/forum/app';
import Component from 'flarum/common/Component';
import Icon from 'flarum/common/components/Icon';
import { bySort, present } from '../../common/utils/fields';
export default class FieldEditDropdown extends Component {
  view() {
    const {
      field,
      answers,
      onchange,
      inputId
    } = this.attrs;
    const suggested = bySort(present(field.suggestedAnswers()));
    const selectedIds = answers.map(answer => answer.id());
    return m("span", {
      className: "Select"
    }, m("select", {
      id: inputId,
      className: "Select-input FormControl",
      multiple: field.multiple(),
      onchange: event => {
        const select = event.target;
        const ids = field.multiple() ? Array.from(select.options).filter(option => option.selected).map(option => option.value) : [select.value];
        onchange(suggested.filter(answer => ids.includes(answer.id())));
      }
    }, !field.multiple() && m("option", {
      value: "",
      selected: !selectedIds.length,
      disabled: field.required(),
      hidden: this.placeholderHidden()
    }, this.placeholder()), suggested.map(answer => m("option", {
      value: answer.id(),
      selected: selectedIds.includes(answer.id())
    }, answer.content()))), m(Icon, {
      name: "fas fa-caret-down",
      className: "Select-caret"
    }));
  }

  /**
   * With labels hidden, the placeholder is the only place the field name shows, so it must stay visible.
   */
  placeholderHidden() {
    return !app.forum.attribute('fof-mason.labels-as-placeholders') && this.attrs.field.required();
  }
  placeholder() {
    const {
      field
    } = this.attrs;
    const prompt = app.translator.trans(field.required() ? 'fof-mason.forum.answers.choose-option' : 'fof-mason.forum.answers.no-option-selected', {}, true);
    if (app.forum.attribute('fof-mason.labels-as-placeholders')) {
      return `${field.name()}${field.required() ? ' *' : ''} - ${prompt}`;
    }
    return prompt;
  }
}
flarum.reg.add('fof-mason', 'forum/components/FieldEditDropdown', FieldEditDropdown);